def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the solid separator rows and columns.
    sep_rows = [r for r in range(h) if grid[r][0] != 0 and all(x == grid[r][0] for x in grid[r])]
    sep_cols = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def regions(size, separators):
        bounds = [-1] + separators + [size]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]

    row_regions = regions(h, sep_rows)
    col_regions = regions(w, sep_cols)

    # The nonempty panel outside the first column contains the pattern to copy.
    pattern = None
    for ri, (r0, r1) in enumerate(row_regions):
        for ci, (c0, c1) in enumerate(col_regions[1:], start=1):
            cells = [(r - r0, c - c0) for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] != 0]
            if cells:
                pattern = cells
                break
        if pattern is not None:
            break

    out = [row[:] for row in grid]

    # Recolor the pattern using each row of panels' seed color.
    for r0, r1 in row_regions:
        seed = next((grid[r][c] for r in range(r0, r1)
                     for c in range(col_regions[0][0], col_regions[0][1])
                     if grid[r][c] != 0), 0)
        for c0, c1 in col_regions:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = 0
            if pattern:
                for dr, dc in pattern:
                    if r0 + dr < r1 and c0 + dc < c1:
                        out[r0 + dr][c0 + dc] = seed

    return out
